<?php
require_once dirname(__DIR__).'/includes/functions.php';require_role('student');verify_csrf();$uid=(int)user()['id'];$jobId=(int)($_POST['job_id']??0);$cover=trim($_POST['cover_letter']??'');
if(mb_strlen($cover)>3000)json_response(['ok'=>false,'message'=>'Keep your cover letter under 3,000 characters.'],422);
$stmt=$con->prepare("SELECT id,title FROM job_opportunities WHERE id=? AND is_active=1 AND (closing_date IS NULL OR closing_date>=CURDATE())");$stmt->bind_param('i',$jobId);$stmt->execute();$job=$stmt->get_result()->fetch_assoc();if(!$job)json_response(['ok'=>false,'message'=>'This opportunity is no longer accepting applications.'],422);
$stmt=$con->prepare('SELECT resume_path FROM users WHERE id=?');$stmt->bind_param('i',$uid);$stmt->execute();$resume=$stmt->get_result()->fetch_assoc()['resume_path']??'';if(!$resume)json_response(['ok'=>false,'message'=>'Upload your resume in your career profile before applying.'],422);
try{$stmt=$con->prepare('INSERT INTO job_applications(job_id,user_id,resume_path,cover_letter) VALUES(?,?,?,?)');$stmt->bind_param('iiss',$jobId,$uid,$resume,$cover);$stmt->execute();notify_user($con,$uid,'job_application','Your application for '.$job['title'].' was submitted.');json_response(['ok'=>true,'message'=>'Application submitted successfully.','reload'=>true]);}catch(mysqli_sql_exception $e){if($e->getCode()===1062)json_response(['ok'=>false,'message'=>'You already applied for this opportunity.'],422);error_log('Job application error: '.$e->getMessage());json_response(['ok'=>false,'message'=>'Your application could not be submitted. Try again.'],500);}
